-- ==============================================================================
-- Migration: AC Backgrounds Normalization & Admin RLS
-- Date: 2026-10-05
-- Target: public.ac_backgrounds
-- Description: Adds ruleset and category columns, sets Staff Admin RLS policies,
--              and updates backgrounds with normalized source keys, rulesets, and categories.
-- ==============================================================================

-- 1. Schema Extensions
ALTER TABLE public.ac_backgrounds ADD COLUMN IF NOT EXISTS ruleset TEXT;
ALTER TABLE public.ac_backgrounds ADD COLUMN IF NOT EXISTS category TEXT;

-- 2. Staff Admin RLS Policies (Idempotent)
DROP POLICY IF EXISTS "Admins and Engineers can manage ac_backgrounds" ON public.ac_backgrounds;
CREATE POLICY "Admins and Engineers can manage ac_backgrounds"
ON public.ac_backgrounds FOR ALL
TO authenticated
USING (
  ((SELECT discord_users.roles FROM discord_users WHERE discord_users.user_id = auth.uid()) @> '["Engineer"]'::jsonb)
  OR ((SELECT discord_users.roles FROM discord_users WHERE discord_users.user_id = auth.uid()) @> '["Admin"]'::jsonb)
)
WITH CHECK (
  ((SELECT discord_users.roles FROM discord_users WHERE discord_users.user_id = auth.uid()) @> '["Engineer"]'::jsonb)
  OR ((SELECT discord_users.roles FROM discord_users WHERE discord_users.user_id = auth.uid()) @> '["Admin"]'::jsonb)
);

